assignments.value:
={{ (() => {
  const memoria = $('Normalizar Contexto').item.json.user_name;
  const nuevo = $('Extraer nombre').isExecuted ? $('Extraer nombre').item.json.output.nombre_cliente : '';
  const nombre = memoria !== 'cliente' ? memoria : nuevo;
  const saludo = nombre ? 'Hola, ' + nombre.split(' ')[0] + '. ' : '';
  return saludo + $('Unificar resultado').item.json.respuesta_cliente;
})() }}

={{ (() => {
  const n = $('Normalizar Contexto').item.json.user_name;
  const nombre = n && n !== 'cliente' ? ', ' + n.split(' ')[0] : '';
  return '¡Gracias a vos' + nombre + '! Cualquier otra consulta, escribinos cuando quieras.';
})() }}
